-- =============================================
-- BASE DE DATOS DE PRÁCTICA SQL
-- Tienda de Electrónicos 'TechStore'
-- =============================================

-- Eliminar tablas si existen
DROP TABLE IF EXISTS detalle_pedidos;
DROP TABLE IF EXISTS pedidos;
DROP TABLE IF EXISTS productos;
DROP TABLE IF EXISTS categorias;
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS empleados;
DROP TABLE IF EXISTS departamentos;
DROP TABLE IF EXISTS regiones;

-- =============================================
-- TABLA: regiones
-- =============================================
CREATE TABLE regiones (
    region_id   INTEGER PRIMARY KEY,
    nombre      VARCHAR(50) NOT NULL,
    pais        VARCHAR(50) NOT NULL DEFAULT 'México'
);


-- =============================================
-- TABLA: departamentos
-- =============================================
CREATE TABLE departamentos (
    departamento_id INTEGER PRIMARY KEY,
    nombre          VARCHAR(80) NOT NULL,
    presupuesto     DECIMAL(12,2),
    region_id       INTEGER REFERENCES regiones(region_id)
);


-- =============================================
-- TABLA: empleados
-- =============================================
CREATE TABLE empleados (
    empleado_id     INTEGER PRIMARY KEY,
    nombre          VARCHAR(50) NOT NULL,
    apellido        VARCHAR(50) NOT NULL,
    email           VARCHAR(100) UNIQUE,
    puesto          VARCHAR(60),
    salario         DECIMAL(10,2),
    fecha_contrato  DATE,
    departamento_id INTEGER REFERENCES departamentos(departamento_id),
    jefe_id         INTEGER REFERENCES empleados(empleado_id)
);





-- =============================================
-- TABLA: categorias
-- =============================================
CREATE TABLE categorias (
    categoria_id    INTEGER PRIMARY KEY,
    nombre          VARCHAR(80) NOT NULL,
    descripcion     TEXT,
    activa          BOOLEAN DEFAULT TRUE
);


-- =============================================
-- TABLA: productos
-- =============================================
CREATE TABLE productos (
    producto_id     INTEGER PRIMARY KEY,
    nombre          VARCHAR(120) NOT NULL,
    marca           VARCHAR(50),
    modelo          VARCHAR(60),
    categoria_id    INTEGER REFERENCES categorias(categoria_id),
    precio_compra   DECIMAL(10,2),
    precio_venta    DECIMAL(10,2),
    stock           INTEGER DEFAULT 0,
    stock_minimo    INTEGER DEFAULT 5,
    activo          BOOLEAN DEFAULT TRUE
);








-- =============================================
-- TABLA: clientes
-- =============================================
CREATE TABLE clientes (
    cliente_id      INTEGER PRIMARY KEY,
    nombre          VARCHAR(50) NOT NULL,
    apellido        VARCHAR(60) NOT NULL,
    email           VARCHAR(100) UNIQUE,
    telefono        VARCHAR(20),
    ciudad          VARCHAR(50),
    estado          VARCHAR(50),
    region_id       INTEGER REFERENCES regiones(region_id),
    fecha_registro  DATE,
    tipo_cliente    VARCHAR(20) DEFAULT 'regular'
);





















-- =============================================
-- TABLA: pedidos
-- =============================================
CREATE TABLE pedidos (
    pedido_id       INTEGER PRIMARY KEY,
    cliente_id      INTEGER REFERENCES clientes(cliente_id),
    empleado_id     INTEGER REFERENCES empleados(empleado_id),
    fecha_pedido    DATE NOT NULL,
    fecha_entrega   DATE,
    estado          VARCHAR(20) DEFAULT 'pendiente',
    total           DECIMAL(12,2),
    descuento       DECIMAL(5,2) DEFAULT 0,
    metodo_pago     VARCHAR(30),
    region_id       INTEGER REFERENCES regiones(region_id)
);









































-- =============================================
-- TABLA: detalle_pedidos
-- =============================================
CREATE TABLE detalle_pedidos (
    detalle_id      INTEGER PRIMARY KEY,
    pedido_id       INTEGER REFERENCES pedidos(pedido_id),
    producto_id     INTEGER REFERENCES productos(producto_id),
    cantidad        INTEGER NOT NULL DEFAULT 1,
    precio_unitario DECIMAL(10,2) NOT NULL,
    descuento_linea DECIMAL(5,2) DEFAULT 0
);














































-- Actualizar totales de pedidos
UPDATE pedidos p SET total = (
    SELECT ROUND(SUM(dp.cantidad * dp.precio_unitario * (1 - dp.descuento_linea/100.0)) * (1 - p.descuento/100.0), 2)
    FROM detalle_pedidos dp WHERE dp.pedido_id = p.pedido_id
);

